sys_ui_script.script:
var x_37790_appxconnec = x_37790_appxconnec || {};

x_37790_appxconnec.appxconnect_adapter = (function () {
	"use strict";

	var isLibLoaded = false;

	function createInteraction(data) {
		/*openFrameAPI.openServiceNowForm({'interaction_sys_id':data.result.interactionId});*/
	}

	function handleCommunicationEvent(context) {
		document
			.getElementById("appxcti")
			.contentWindow.postMessage({ command: "CLICK2CALL", data: context }, "*");
		openFrameAPI.show();
	}

	function initSuccess(snConfig) {
		//register for communication event from TopFrame
		openFrameAPI.subscribe(
			openFrameAPI.EVENTS.COMMUNICATION_EVENT,
			handleCommunicationEvent
		);
		isLibLoaded = true;
		document.getElementById("appxcti").src =
			"https://cti.appxconnect.com?ctiid=" + snConfig["configuration"];
	}

	function initFailure(error) {}

	function isCRMLoaded(task) {
		var tempTask = {
			command: task.command,
			jobuuid: task.jobuuid,
			data: {
				crmloaded: true,
			},
		};
		document.getElementById("appxcti").contentWindow.postMessage(tempTask, "*");
	}

	return {
		snOnLoad: function () {
			window.addEventListener("message", function (event) {
				if (event.data.command) {
					var command = event.data.command;
					if (command == "LOADLIB") {
						isCRMLoaded(event.data);
					} else if (command == "SEARCHENTITY") {
						x_37790_appxconnec.servicenow_adapter.searchEnt(event.data);
					} else if (command == "CREATEENTITY") {
						if (event.data.data) {
							if (event.data.data.snEntityName) {
								if (event.data.data.snEntityName == "interaction") {
									if (
										event.data.data.snEntityDetails.interactionSysId == "" ||
										event.data.data.snEntityDetails.interactionSysId == "-1"
									) {
										x_37790_appxconnec.servicenow_adapter.createInteraction(
											event.data
										);
									} else {
										x_37790_appxconnec.servicenow_adapter.updateInteraction(
											event.data
										);
									}
								}
							}
						}
					} else if (command == "UPDATEENTITY") {
						if (event.data.data) {
							if (event.data.data.snEntityName) {
								if (event.data.data.snEntityName == "interaction") {
									if (
										event.data.data.snEntityDetails.interactionSysId == "" ||
										event.data.data.snEntityDetails.interactionSysId == "-1"
									) {
										x_37790_appxconnec.servicenow_adapter.createInteraction(
											event.data
										);
									} else {
										x_37790_appxconnec.servicenow_adapter.updateInteraction(
											event.data
										);
									}
								}
							}
						}
					} else if (command == "OPENENTITY") {
						openFrameAPI.openServiceNowForm(event.data.data.snData);
					} else if (command == "OPENECFORM") {
						openFrameAPI.openServiceNowForm(event.data.data.snData);
					} else if (command == "OPENCTIWINDOW") {
						openFrameAPI.show();
					} else {
						openFrameAPI.openServiceNowForm(event.data.data);
					}
				}
			});
			openFrameAPI.init({}, initSuccess, initFailure);
		},
		/* set your public API here. For example:
        		incrementAndReturnPrivateVar: function() {
        			return private_function();
        		},
        */
		type: "appxconnect_adapter",
	};
})();
